const T=api.t,W=api.w,H=api.h;
const tri=T<0.42?T/0.42:1-(T-0.42)/0.58;
const adv=tri*tri*(3-2*tri);
const base=H*1.02, run=p.reach*H*0.86;
const front=base-adv*run;
for(let x=0;x<W;x++){
  const wob=Math.sin(x*0.42+2*Math.PI*T)*p.wobble+Math.sin(x*0.15+2.1)*p.wobble*0.6;
  const fy=Math.round(front+wob);
  if(fy>=H)continue;
  const wet=Math.round(fy-2-p.wobble);
  for(let y=Math.max(0,wet);y<fy;y++)api.px(x,y,3,0.2*p.intensity);
  const bh=H-fy;
  if(bh>0){
    api.rect(x,fy,1,bh,1,0.85*p.intensity);
    api.rect(x,fy+Math.max(1,Math.round(bh*0.55)),1,Math.max(1,Math.round(bh*0.45)),3,0.35*p.intensity);
    api.px(x,fy+Math.round(bh*0.45+Math.sin(x*0.3+2*Math.PI*T*2)*1.2),0,0.22*p.intensity);
  }
  const lip=Math.max(1,Math.round(p.foam*(0.45+0.55*adv)));
  for(let k=0;k<lip;k++){
    const a=(1-k/(lip+0.6))*(0.55+0.45*adv)*p.intensity;
    api.px(x,fy+k,0,a);
  }
  if(adv>0.5&&(x+Math.round(T*7))%3===0)api.px(x,fy-1,0,(adv-0.5)*1.5*p.intensity);
}
const nd=Math.round(p.drops);
for(let i=0;i<nd;i++){
  const st=0.2+api.rnd(i*7+1)*0.2;
  const u=(T-st)/0.3;
  if(u<=0||u>=1)continue;
  const sx=api.rnd(i*7+2)*W;
  const sy=base-run*(0.35+api.rnd(i*7+5)*0.4);
  const vx=(api.rnd(i*7+3)-0.5)*12;
  const vy=5+api.rnd(i*7+4)*7;
  const x=Math.round(sx+vx*u);
  const y=Math.round(sy-(vy*u*2.0-13*u*u));
  const a=(1-u)*(1-u)*1.2*p.intensity;
  api.px(x,y,u<0.55?0:1,a);
  if(u<0.4)api.px(x,y+1,0,a*0.45);
}
